package com.xyzbroker.cashoutapp.data.remote.network.common

import com.google.gson.JsonSyntaxException
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.runBlocking
import okhttp3.Headers.Companion.headersOf
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.Protocol
import okhttp3.Request
import okhttp3.ResponseBody.Companion.toResponseBody
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import retrofit2.Response
import java.io.IOException
import java.math.BigDecimal
import java.net.ConnectException
import java.net.SocketTimeoutException

class SafeApiCallTest {

    private fun errorResponse(
        code: Int,
        body: String,
        contentType: String = "application/json",
        headers: Map<String, String> = emptyMap(),
    ): Response<String> {
        val raw = okhttp3.Response.Builder()
            .request(Request.Builder().url("http://localhost/").build())
            .protocol(Protocol.HTTP_1_1)
            .code(code)
            .message("error")
            .apply { headers.forEach { (k, v) -> header(k, v) } }
            .build()
        return Response.error(body.toResponseBody(contentType.toMediaType()), raw)
    }

    private fun run(call: suspend () -> Response<String>) = runBlocking { safeApiCall(call) }

    @Test
    fun success_reportsReplayHeader() {
        val result = run { Response.success("ok", headersOf("Idempotent-Replayed", "true")) }
        assertEquals(NetworkResult.Success("ok", replayed = true), result)
    }

    @Test
    fun success_withoutReplayHeader_isNotReplayed() {
        val result = run { Response.success("ok") }
        assertEquals(NetworkResult.Success("ok", replayed = false), result)
    }

    @Test
    fun problemBody_keepsCodeAndExactMoney() {
        val body = """{"code":"INSUFFICIENT_FUNDS","detail":"x","correlationId":"c-1","maxWithdrawable":1250.50}"""
        val result = run { errorResponse(422, body) } as NetworkResult.HttpError

        assertEquals(422, result.status)
        assertEquals("INSUFFICIENT_FUNDS", result.problem?.code)
        assertEquals("c-1", result.problem?.correlationId)
        assertEquals(BigDecimal("1250.50"), result.problem?.maxWithdrawable)
    }

    @Test
    fun problemBody_keepsFieldErrors() {
        val body = """{"code":"VALIDATION_ERROR","fieldErrors":{"iban":"INVALID_IBAN","beneficiaryName":"INVALID_NAME"}}"""
        val result = run { errorResponse(422, body) } as NetworkResult.HttpError

        assertEquals(
            mapOf("iban" to "INVALID_IBAN", "beneficiaryName" to "INVALID_NAME"),
            result.problem?.fieldErrors,
        )
    }

    @Test
    fun rateLimited_readsRetryAfterHeader() {
        val body = """{"code":"RATE_LIMITED","retryAfterSeconds":30}"""
        val result = run { errorResponse(429, body, headers = mapOf("Retry-After" to "30")) } as NetworkResult.HttpError

        assertEquals(30L, result.retryAfterSeconds)
        assertEquals(30L, result.problem?.retryAfterSeconds)
    }

    @Test
    fun gatewayHtml_hasNoProblem() {
        val result = run { errorResponse(502, "<html><body>Bad Gateway</body></html>", "text/html") }
            as NetworkResult.HttpError

        assertEquals(502, result.status)
        assertNull(result.problem)
    }

    @Test
    fun connectFailure_isNotSent() {
        val result = run { throw ConnectException("refused") }
        assertTrue(result is NetworkResult.NotSent)
    }

    @Test
    fun connectFailureAfterEarlierAttempt_mayHaveBeenSent() {
        val result = run {
            throw ConnectException("refused").apply { addSuppressed(IOException("stream reset")) }
        }
        assertTrue(result is NetworkResult.NoUsableResponse)
    }

    @Test
    fun readTimeout_mayHaveBeenSent() {
        val result = run { throw SocketTimeoutException("timeout") }
        assertTrue(result is NetworkResult.NoUsableResponse)
    }

    @Test
    fun unparseableSuccessBody_mayHaveBeenSent() {
        val result = run { throw JsonSyntaxException("bad body") }
        assertTrue(result is NetworkResult.NoUsableResponse)
    }

    @Test(expected = CancellationException::class)
    fun cancellation_isRethrown() {
        run { throw CancellationException("cancelled") }
    }
}
